// three.js pieces shared by the walk mode and the outpost backdrop: textures from our generated bytes, the
// giant planet that hangs in a moon's sky, and the liquid / lava pool surface.
import * as THREE from 'three';
import { cachedTexture, generateGasGiantTexture, generateRingTexture, generateLavaTexture } from './textures.js';

const DEG = Math.PI / 180;
const RING_INNER = 1.25; // in planet radii
const RING_OUTER = 2.25;
const RING_TILT = 76 * DEG;
const LAVA_FLOW_SPEED = 0.004; // texture widths per second

/** Wraps generated RGBA bytes (see textures.js) as a GPU texture. */
export function dataTexture(tex, { repeat = false, anisotropy = 1 } = {}) {
  const t = new THREE.DataTexture(tex.data, tex.width, tex.height, THREE.RGBAFormat);
  t.colorSpace = THREE.SRGBColorSpace;
  t.wrapS = THREE.RepeatWrapping;
  t.wrapT = repeat ? THREE.RepeatWrapping : THREE.ClampToEdgeWrapping;
  t.magFilter = THREE.LinearFilter;
  t.minFilter = THREE.LinearMipmapLinearFilter;
  t.generateMipmaps = true;
  t.anisotropy = anisotropy;
  t.needsUpdate = true;
  return t;
}

const BODY_VERT = /* glsl */ `
  varying vec3 vN; varying vec2 vUv; varying float vR;
  void main() {
    vUv = uv;
    vR = length(position.xy);
    vN = normalize(mat3(modelMatrix) * normal);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;
const PLANET_FRAG = /* glsl */ `
  uniform sampler2D uMap; uniform vec3 uSunDir;
  varying vec3 vN; varying vec2 vUv;
  void main() {
    float lit = smoothstep(-0.08, 0.35, dot(normalize(vN), uSunDir));
    gl_FragColor = vec4(texture2D(uMap, vUv).rgb * (0.05 + lit * 1.25), 1.0);
    #include <tonemapping_fragment>
    #include <colorspace_fragment>
  }
`;
const RING_FRAG = /* glsl */ `
  uniform sampler2D uMap; uniform float uInner, uOuter;
  varying float vR;
  void main() {
    vec4 ring = texture2D(uMap, vec2(clamp((vR - uInner) / (uOuter - uInner), 0.0, 1.0), 0.5));
    gl_FragColor = vec4(ring.rgb * 0.9, ring.a);
    #include <tonemapping_fragment>
    #include <colorspace_fragment>
  }
`;

/**
 * Jupiter or Saturn as seen from one of their moons, sized by its real angular width.
 * @param {{ id: string, angularSizeDeg: number, bands: string[], rings: boolean }} parent
 * @param {{ distance: number, sunDir: THREE.Vector3, detail?: number }} opts sunDir is shared with the sky and updated by it.
 */
export function createParentBody(parent, { distance, sunDir, detail = 32 }) {
  const radius = distance * Math.tan((parent.angularSizeDeg / 2) * DEG);
  const group = new THREE.Group();
  const map = dataTexture(cachedTexture(`giant:${parent.id}`, () => generateGasGiantTexture(parent, 256, parent.id.length * 31)));
  const planetMat = new THREE.ShaderMaterial({ vertexShader: BODY_VERT, fragmentShader: PLANET_FRAG, uniforms: { uMap: { value: map }, uSunDir: { value: sunDir } }, fog: false });
  const planet = new THREE.Mesh(new THREE.SphereGeometry(radius, detail, Math.max(8, detail >> 1)), planetMat);
  planet.rotation.z = 0.12;
  group.add(planet);
  const owned = [map, planetMat, planet.geometry];
  if (parent.rings) {
    const ringMap = dataTexture(cachedTexture('giant:rings', () => generateRingTexture(256, 7)));
    const ringMat = new THREE.ShaderMaterial({
      vertexShader: BODY_VERT, fragmentShader: RING_FRAG, transparent: true, depthWrite: false, side: THREE.DoubleSide, fog: false,
      uniforms: { uMap: { value: ringMap }, uInner: { value: radius * RING_INNER }, uOuter: { value: radius * RING_OUTER } },
    });
    const ring = new THREE.Mesh(new THREE.RingGeometry(radius * RING_INNER, radius * RING_OUTER, 64, 1), ringMat);
    ring.rotation.x = RING_TILT;
    ring.rotation.y = 0.12;
    group.add(ring);
    owned.push(ringMap, ringMat, ring.geometry);
  }
  group.traverse((o) => { o.frustumCulled = false; });
  return {
    group,
    setDirection(dir) {
      group.position.set(dir.x * distance, dir.y * distance, dir.z * distance);
      group.lookAt(group.parent ? group.parent.position : new THREE.Vector3()); // keep the cloud bands level as seen from the ground
    },
    dispose() { owned.forEach((o) => o.dispose()); },
  };
}

/**
 * Material for the flat pool surface: glowing lava, or dark glassy liquid (water, Titan's methane).
 * @param {object} look world look
 * @param {{ tiles?: number }} [opts] how many times the lava pattern repeats across the mesh's UV range
 */
export function createPoolMaterial(look, { tiles = 1 } = {}) {
  if (look.lava > 0) {
    const map = dataTexture(cachedTexture('lava:256', () => generateLavaTexture(256, 11)), { repeat: true });
    map.repeat.set(tiles, tiles);
    const material = new THREE.MeshBasicMaterial({ map });
    material.color.setScalar(1.5); // brighter than white so it still glows after tone mapping
    return {
      material, glow: true,
      update(time) { map.offset.set(time * LAVA_FLOW_SPEED, time * LAVA_FLOW_SPEED * 0.6); },
      dispose() { map.dispose(); material.dispose(); },
    };
  }
  const methane = look.liquid?.kind === 'methane';
  // Phong, not a mirror: at walking height a mirror only shows the sky, and Titan's lakes should read dark with a
  // sharp glint from the star.
  const material = new THREE.MeshPhongMaterial({ color: look.liquid?.color ?? '#1f4a66', specular: methane ? '#8a6a48' : '#9fb4c4', shininess: 160, transparent: true, opacity: methane ? 0.97 : 0.88 });
  return { material, glow: false, update() {}, dispose() { material.dispose(); } };
}
